function deliveryBadge(status){return '<span class="badge '+(['sent','simulated'].includes(status)?'green':status==='review_required'?'red':'amber')+'">'+tx(({queued:'في الانتظار',sent:'مُرسل',simulated:'محاكاة',sending:'قيد الإرسال',review_required:'يحتاج مراجعة'})[status]||status,({queued:'Queued',sent:'Sent',simulated:'Simulated',sending:'Sending',review_required:'Needs review'})[status]||status)+'</span>';}
function payrollEffects(id){const r=state.payroll.find(r=>r.id===id);if(!r)return;const effects=hrPayrollEffects(state,r),p=state.settings.attendancePolicy;modal('<h2>'+tx('راجع التأثير قبل التطبيق','Review adjustments before applying')+'</h2><p>'+tx('الحضور مقابل شفتات منشورة؛ الإضافي والمصروفات من الطلبات المعتمدة فقط.','Attendance against published shifts; overtime and expenses from approved requests only.')+'</p><div class="notice blue">'+tx('خصم الدقيقة','Late minute')+': '+p.lateRate+' · '+tx('غياب اليوم','Absent day')+': '+p.absenceRate+' · '+tx('ساعة إضافي','Overtime hour')+': '+p.overtimeRate+' '+state.settings.currency+'</div>'+table([tx('الموظف','Employee'),tx('بدلات إضافية','Extra allowances'),tx('مكافآت','Bonus'),tx('خصومات','Deductions'),tx('طلبات','Requests')],effects.filter(x=>x.effects.allowance||x.effects.bonus||x.effects.deduction||x.effects.requestIds.length).map(x=>'<tr><td>'+esc(person(x.employeeId)?.name)+'</td><td>'+fmt(x.effects.allowance)+'</td><td>'+fmt(x.effects.bonus)+'</td><td>'+fmt(x.effects.deduction)+'</td><td>'+x.effects.requestIds.length+'</td></tr>'))+'<p>'+tx('التطبيق يستبدل حساب التأثير السابق، ولا يكرر إضافته.','Applying replaces the earlier adjustment calculation; it does not add it twice.')+'</p><div class="form-actions">'+btn(tx('تطبيق على المسودة','Apply to draft'),'applyPayrollEffects',id,'primary')+btn(tx('إلغاء','Cancel'),'close')+'</div>');}
const REPORTS=[['headcount','دليل الموظفين','People register'],['attendance','ملخص الحضور','Attendance summary'],['leaves','طلبات الإجازات','Leave requests'],['requests','متابعة الطلبات','Request tracking'],['contracts','انتهاء العقود','Contract expiry'],['documents','نواقص التعيين','Missing documents'],['payroll','تفاصيل المرتبات','Payroll detail'],['payments','سجل الصرف','Payment register'],['turnover','حركة الموظفين','Employee movement'],['onboarding','تقدم التهيئة','Onboarding progress'],['audit','سجل الإجراءات','Activity audit']];
function actionTitle(a){const names={'request.create':['إنشاء طلب','Request created'],'request.decide':['قرار على طلب','Request decision'],'request.cancel':['سحب طلب','Request withdrawn'],'request.fulfill':['تنفيذ طلب','Request fulfilled'],'leave.create':['طلب إجازة','Leave requested'],'leave.decide':['قرار إجازة','Leave decision'],'workflow.save':['تعديل مسار موافقة','Approval workflow changed'],'shift.save':['تعديل شفت','Shift updated'],'shift.publish':['نشر شفتات','Shifts published'],'shift.remove':['حذف شفت','Shift removed'],'contract.save':['تسجيل عقد','Contract recorded'],'document.register':['رفع مستند','Document uploaded'],'document.review':['مراجعة مستند','Document reviewed'],'document.expiry':['تحديث صلاحية مستند','Document expiry updated'],'attendance.record':['تسجيل حضور','Attendance recorded'],'attendance.policy':['تعديل سياسة احتساب','Attendance calculation updated'],'payroll.prepare':['تجهيز مرتبات','Payroll prepared'],'payroll.effects':['تطبيق تأثيرات المرتب','Payroll adjustments applied'],'payroll.approve':['اعتماد مرتبات','Payroll approved'],'payroll.payment':['تسجيل صرف','Payment recorded'],'payroll.updateRow':['تعديل بند راتب','Payroll input changed'],'payroll.simulate':['محاكاة إرسال','Delivery simulated'],'employee.add':['إضافة موظف','Employee added'],'employee.edit':['تعديل ملف موظف','Employee profile updated'],'access.set':['تحديث صلاحية','Access role changed'],'onboarding.complete':['إقرار سياسة','Policy acknowledged'],'offboarding.add':['بدء إخلاء طرف','Offboarding started'],'offboarding.task':['تحديث إخلاء طرف','Handover updated'],'offboarding.finalize':['إغلاق ملف موظف','Employee archived'],'settings.save':['تعديل إعدادات','Settings changed']};return names[a]?tx(...names[a]):esc(a);}
function reportData(kind){const es=scopedEmployees(),ids=new Set(es.map(e=>e.id)),inRange=d=>d&&d.slice(0,10)>=from&&d.slice(0,10)<=to;let headers=[],rows=[];
 if(kind==='headcount'){headers=[tx('الموظف','Employee'),tx('القسم','Department'),tx('المسمى','Job title'),tx('الانضمام','Joined'),tx('الحالة','Status')];rows=es.filter(e=>e.joinDate<=to&&(!e.exitDate||e.exitDate>to)).map(e=>[e.name,e.department,e.job,e.joinDate,tx(e.status==='active'?'نشط':e.status==='inactive'?'منتهية الخدمة':'تهيئة',e.status)]);}
 if(kind==='attendance'){headers=[tx('الموظف','Employee'),tx('السجلات','Records'),tx('ساعات العمل','Work hours'),tx('التأخير بالدقائق','Late minutes'),tx('غياب مجدول','Scheduled absence')];rows=es.map(e=>{const s=hrAttendanceStats(state,e.id,from,to);return[e.name,s.records,fmt(s.workedMinutes/60),s.lateMinutes,s.absentDays];});}
 if(kind==='leaves'){headers=[tx('الموظف','Employee'),tx('النوع','Type'),tx('من','From'),tx('إلى','Until'),tx('الأيام','Days'),tx('الحالة','Status')];rows=state.leaves.filter(l=>ids.has(l.employeeId)&&l.from<=to&&l.to>=from).map(l=>[person(l.employeeId)?.name,l.type,l.from,l.to,l.days,tx(({pending:'قيد الموافقة',approved:'معتمد',rejected:'مرفوض',cancelled:'مسحوب'})[l.status]||l.status,l.status)]);}
 if(kind==='requests'){headers=[tx('الموظف','Employee'),tx('الطلب','Request'),tx('التاريخ','Date'),tx('الحالة','Status'),tx('المرحلة الحالية','Current step')];rows=allRequests().filter(r=>ids.has(r.employeeId)&&inRange(r.createdAt)).map(r=>[person(r.employeeId)?.name,typeName(r.type),r.createdAt.slice(0,10),tx(({pending:'قيد الموافقة',approved:'معتمد',rejected:'مرفوض',cancelled:'مسحوب'})[r.status]||r.status,r.status),r.status==='pending'?roleName(r.workflow[r.stage]):'—']);}
 if(kind==='contracts'){headers=[tx('الموظف','Employee'),tx('بداية العقد','Contract starts'),tx('نهاية العقد','Contract ends'),tx('الحالة','Status')];rows=state.contracts.filter(c=>ids.has(c.employeeId)&&inRange(c.end)).map(c=>[person(c.employeeId)?.name,c.start,c.end,tx(c.status==='renewed'?'تم التجديد':'ساري',c.status)]);}
 if(kind==='documents'){headers=[tx('الموظف','Employee'),tx('القسم','Department'),tx('نواقص الموافقة','Missing approvals')];rows=documentGaps().map(x=>[x.employee.name,x.employee.department,x.missing.join(' / ')]);}
 if(kind==='payroll'){headers=[tx('الشهر','Month'),tx('الموظف','Employee'),tx('الأساسي','Base'),tx('البدلات','Allowances'),tx('المكافآت','Bonus'),tx('الخصومات','Deductions'),tx('الصافي','Net')];rows=state.payroll.filter(r=>r.month>=from.slice(0,7)&&r.month<=to.slice(0,7)).flatMap(r=>r.rows.filter(x=>ids.has(x.employeeId)).map(x=>{const p=hrPayParts(x);return[r.month,x.name,p.basic,p.allowance,p.bonus,p.deduction,p.net];}));}
 if(kind==='payments'){headers=[tx('الشهر','Month'),tx('الصافي الكلي','Full run net'),tx('حالة الصرف','Payment status'),tx('التاريخ','Date'),tx('المرجع','Reference')];rows=state.payroll.filter(r=>r.month>=from.slice(0,7)&&r.month<=to.slice(0,7)).map(r=>[r.month,r.rows.reduce((n,x)=>n+x.net,0),r.paymentStatus==='paid'?tx('مسجل','Recorded'):tx('غير مسجل','Not recorded'),r.paymentDate||'—',r.paymentReference||'—']);}
 if(kind==='turnover'){headers=[tx('الموظف','Employee'),tx('القسم','Department'),tx('الحركة','Movement'),tx('التاريخ','Date')];rows=state.employees.filter(e=>!department||e.department===department).flatMap(e=>[...(inRange(e.joinDate)?[[e.name,e.department,tx('انضمام','Joined'),e.joinDate]]:[]),...(inRange(e.exitDate)?[[e.name,e.department,tx('مغادرة','Exited'),e.exitDate]]:[])]);}
 if(kind==='onboarding'){headers=[tx('الموظف','Employee'),tx('الانضمام','Joined'),tx('السياسات','Policies'),tx('المستندات المقبولة','Approved documents')];rows=es.filter(e=>inRange(e.joinDate)).map(e=>[e.name,e.joinDate,e.onboarding.length+'/'+state.policies.length,state.documents.filter(d=>d.employeeId===e.id&&d.active!==false&&d.status==='approved').length+'/'+state.settings.requiredDocuments.length]);}
 if(kind==='audit'){headers=[tx('الوقت','Time'),tx('المستخدم','Actor'),tx('الإجراء','Action'),tx('المرجع','Reference'),tx('ملاحظة','Note')];rows=state.audit.filter(a=>inRange(a.at)).map(a=>[a.at.slice(0,16).replace('T',' '),a.actor,actionTitle(a.action),a.recordId||'—',a.summary||'']);}
 return {headers,rows};
}
function availableReports(){return REPORTS.filter(r=>isHR()||role==='finance'&&['payroll','payments','requests'].includes(r[0])||role==='manager'&&['headcount','attendance','leaves','requests','turnover'].includes(r[0]));}
function reportsPage(){const available=availableReports();if(!available.some(r=>r[0]===reportKind))reportKind=available[0]?.[0]||'headcount';const d=reportData(reportKind),title=available.find(r=>r[0]===reportKind);return heading(tx('إجابات من بياناتك.','Answers from your records.'),tx('تقارير داخل النظام، قابلة للتصفية والطباعة إلى PDF.','In-app reports, with filters and print-to-PDF.'),btn(tx('طباعة / PDF','Print / PDF'),'print','','primary'),'REPORTS & AUDIT')+'<div class="report-layout"><aside class="report-menu">'+available.map(r=>'<button data-action="reportKind" data-id="'+r[0]+'" class="'+(reportKind===r[0]?'active':'')+'">'+tx(r[1],r[2])+'</button>').join('')+'</aside><div>'+filters()+card(title?tx(title[1],title[2]):'',d.rows.length+' '+tx('سجل','records')+' · '+(reportKind==='documents'?tx('النواقص الحالية؛ فلتر التاريخ لا ينطبق','Current missing documents; date range does not apply'):reportKind==='payments'?tx('إجمالي الكشف؛ فلتر القسم لا ينطبق','Full payroll runs; department filter does not apply'):reportKind==='audit'?tx('سجل النظام؛ فلتر القسم لا ينطبق','System activity; department filter does not apply'):from+' → '+to),table(d.headers,d.rows.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>')))+'</div></div>';}
function orgchartPage(){const es=scopedEmployees(),managers=es.filter(e=>es.some(x=>x.manager===e.id&&x.id!==e.id)),unassigned=es.filter(e=>!e.manager||!es.some(x=>x.id===e.manager));return heading(tx('مين مسؤول عن مين؟','See how your team connects.'),tx('الهيكل مبني على المدير المباشر المسجل في ملف كل موظف.','Built from the line manager recorded on each employee profile.'),'','ORGANISATION')+filters(true)+'<div class="org-root"><span class="eyebrow">'+esc(state.settings.company)+'</span><h2>'+tx('الهيكل التنظيمي','Organisation chart')+'</h2><p>'+es.length+' '+tx('موظف ظاهر حسب الصلاحية والفلاتر','employees visible under your access and filters')+'</p></div><div class="org-grid">'+managers.map(m=>'<section class="card org-team"><div class="org-manager">'+avatar(m)+'</div><div>'+es.filter(e=>e.manager===m.id&&e.id!==m.id).map(e=>'<button data-action="profile" data-id="'+e.id+'" class="org-person">'+avatar(e)+'</button>').join('')+'</div></section>').join('')+(unassigned.length?card(tx('الإدارة / بدون مدير ظاهر','Leadership / no visible manager'),'',unassigned.map(e=>'<button class="org-person" data-action="profile" data-id="'+e.id+'">'+avatar(e)+'</button>').join('')):'')+'</div>';}
function commandPalette(){modal('<span class="eyebrow">FIND YOUR NEXT STEP</span><h2>'+tx('أين تريد الوصول؟','Where do you want to go?')+'</h2><input id="commandSearch" class="command-input" placeholder="'+tx('ابحث عن صفحة أو موظف…','Search pages or people…')+'" aria-label="'+tx('البحث السريع','Quick search')+'" autofocus><div id="commandResults"></div>');commandResults('');$('commandSearch').focus();}
function commandResults(search){const q=search.trim().toLowerCase(),pages=allowedPages().filter(k=>!['portal','settings'].includes(k)&&(routeLabel(k).toLowerCase().includes(q)||k.includes(q))),people=scopedEmployees().filter(e=>q&&(e.name+' '+e.id+' '+e.job).toLowerCase().includes(q)).slice(0,8);$('commandResults').innerHTML='<div class="command-results">'+pages.map(k=>'<button data-action="commandNav" data-id="'+k+'"><span>'+routeLabel(k)+'</span><small>'+tx('صفحة','Page')+'</small></button>').join('')+people.map(e=>'<button data-action="profile" data-id="'+e.id+'"><span>'+esc(e.name)+'</span><small>'+esc(e.job)+'</small></button>').join('')+(!pages.length&&!people.length?'<div class="empty">'+tx('لا توجد نتائج','No results')+'</div>':'')+'</div>';}
function quickCreate(){modal('<h2>'+tx('إجراء سريع','Quick action')+'</h2><div class="request-picker">'+btn(tx('طلب جديد','New request'),'requestPicker')+(isHR()?btn(tx('إضافة موظف','Add employee'),'employeeForm')+btn(tx('إضافة عقد','Add contract'),'contractForm')+btn(tx('تسجيل حضور','Record attendance'),'attendanceForm'):'')+((isHR()||role==='manager')?btn(tx('إضافة شفت','Add shift'),'shiftForm'):'')+'</div>');}
document.addEventListener('click',async ev=>{
 const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id||'';
 try{
  if(a==='command')commandPalette();if(a==='commandNav'){closeModal();navigate(id);}if(a==='quickCreate')quickCreate();
  if(a==='datePreset'){const today=hrToday();from=id==='30'?datePlus(today,-29):id==='quarter'?today.slice(0,4)+'-'+String(Math.floor((Number(today.slice(5,7))-1)/3)*3+1).padStart(2,'0')+'-01':today.slice(0,7)+'-01';to=today;render();}
  if(a==='allMyRequests'){requestView='mine';requestTypeFilter='';navigate('requests');}if(a==='requestPicker')requestPicker();if(a==='newRequest')newRequest(id);if(a==='requestView'){requestView=id;render();}if(a==='requestDetail')requestDetail(id);
  if(a==='showLeaveRequests'){requestTypeFilter='leave';requestView='all';navigate('requests');}
  if(a==='workflows')workflows();if(a==='editWorkflow')editWorkflow(id);
  if(a==='withdrawRequest'){const [source,rid]=id.split('|');modal('<h2>'+tx('سحب الطلب؟','Withdraw this request?')+'</h2><p>'+tx('سيتوقف مسار الموافقات ولن يُخصم رصيد الإجازة.','The approval workflow stops and no leave balance is deducted.')+'</p><form data-ops="request.cancel"><input type="hidden" name="source" value="'+source+'"><input type="hidden" name="id" value="'+rid+'"><button class="btn danger" type="submit">'+tx('تأكيد السحب','Confirm withdrawal')+'</button></form>');}
  if(a==='fulfillRequest'){const r=state.requests.find(r=>r.id===id);opsForm(tx('توثيق تنفيذ الطلب','Record fulfillment'),'<input type="hidden" name="id" value="'+id+'">'+(['resignation','termination'].includes(r.type)?'<div class="notice blue">'+tx('سينشئ هذا الإجراء حالة إخلاء طرف بتاريخ الطلب. إنهاء الموظف يتطلب إكمال الإخلاء وبلوغ آخر يوم عمل.','This creates an offboarding case using the request date. Employee deactivation still requires completed handover and the last working day.')+'</div>':'')+field(tx('ما الذي تم تنفيذه؟','What action was completed?'),'note'),'request.fulfill');}
  if(a==='shiftWeek'){scheduleStart=datePlus(scheduleStart,Number(id));render();}if(a==='shiftForm')shiftForm(id);if(a==='publishWeek')await mutate('shift.publish',{from:scheduleStart,to:datePlus(scheduleStart,6),department},tx('تم نشر شفتات الأسبوع','Week published'));
  if(a==='shiftDetails'){const s=state.shifts.find(s=>s.id===id);modal('<h2>'+tx('تفاصيل الشفت','Shift details')+'</h2><p>'+esc(s.location)+'</p><p class="mono">'+s.date+' · '+s.start+' → '+s.end+'</p><p>'+s.breakMinutes+' '+tx('دقيقة راحة','break minutes')+'</p>');}
  if(a==='attendanceForm')attendanceForm();if(a==='attendancePolicy')attendancePolicy();
  if(a==='archiveTab'){archiveTab=id;render();}if(a==='contractForm')contractForm(id);
  if(a==='documentExpiry'){const d=state.documents.find(d=>d.id===id);opsForm(tx('تاريخ صلاحية المستند','Document expiry'),'<input type="hidden" name="id" value="'+id+'"><div class="field"><label for="docExpiry">'+tx('اتركه فارغًا إذا لم توجد صلاحية','Leave blank when there is no expiry')+'</label><input id="docExpiry" name="expiresAt" type="date" value="'+(d.expiresAt||'')+'"></div>','document.expiry');}
  if(a==='payrollEffects')payrollEffects(id);if(a==='applyPayrollEffects')await mutate('payroll.effects',{id},tx('تم تطبيق التأثيرات على المسودة','Draft adjustments applied'));
  if(a==='recordPayment')opsForm(tx('تسجيل صرف المرتبات','Record payroll payment'),'<input type="hidden" name="id" value="'+id+'"><div class="notice blue">'+tx('يسجل مرجع عملية تمت بالفعل. هذا الزر لا يحول أموالًا.','Records a payment already completed. This action does not transfer money.')+'</div>'+field(tx('تاريخ الصرف','Payment date'),'date','date',hrToday())+field(tx('مرجع أو إثبات الصرف','Payment reference'),'reference'),'payroll.payment');
  if(a==='reportKind'){reportKind=id;render();}
 }catch(err){toast(err.message||String(err));}
});
document.addEventListener('submit',async ev=>{const f=ev.target;if(!f.dataset.ops)return;ev.preventDefault();const fd=new FormData(f),p=Object.fromEntries(fd.entries());if(f.dataset.ops==='attendance.policy')p.weekend=fd.getAll('weekend').map(Number);if(f.dataset.ops==='workflow.save')p.steps=[p.step0,p.step1,p.step2].filter(Boolean);await mutate(f.dataset.ops,p,tx('تم الحفظ وتسجيل الإجراء','Saved and recorded'));});
document.addEventListener('change',ev=>{if(ev.target.id==='requestTypeFilter'){requestTypeFilter=ev.target.value;render();}if(ev.target.id==='scheduleStart'&&ev.target.value){scheduleStart=ev.target.value;render();}});
document.addEventListener('input',ev=>{if(ev.target.id==='commandSearch')commandResults(ev.target.value);if(ev.target.id==='requestSearch'){requestSearch=ev.target.value;const n=ev.target.selectionStart;render();$('requestSearch').focus();$('requestSearch').setSelectionRange(n,n);}});
document.addEventListener('keydown',ev=>{if((ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();commandPalette();}if(ev.key==='Escape'){setSidebar(false);$('accountMenu').open=false;}});

function prepareMonthForm(){const last=new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5,7)),0,12)).toISOString().slice(0,10);opsForm(tx('تجهيز مسودة المرتبات','Prepare payroll draft'),'<input type="hidden" name="month" value="'+month+'">'+'<div class="form-grid">'+field(tx('بداية احتساب الحضور والطلبات','Attendance & request cut-off start'),'periodFrom','date',month+'-01')+field(tx('نهاية فترة الاحتساب','Cut-off end'),'periodTo','date',last)+'</div><p>'+tx('تحدد هذه الفترة تأثيرات الحضور والطلبات، ويجب ألا تتداخل مع كشف سابق. الرواتب الأساسية لا تُحسب بنسبة أيام العمل تلقائيًا؛ راجعها قبل الاعتماد.','This period controls attendance and request adjustments and must not overlap an existing payroll. Base pay is not prorated automatically; review it before approval.')+'</p>','payroll.prepare');}

function filters(search=false,forceNoRange=false){
 const range=!forceNoRange&&!['employees','leaves','documents','orgchart'].includes(page)&&!(page==='reports'&&reportKind==='documents'),dept=!(page==='reports'&&['payments','audit'].includes(reportKind));
 const wrap=(label,id,control,cls='')=>'<div class="filter-field '+cls+'"><label for="'+id+'">'+label+'</label>'+control+'</div>';
 return '<div class="filters">'+(search?wrap(tx('بحث الموظفين','Search people'),'search','<input id="search" value="'+esc(query)+'" placeholder="'+tx('الاسم أو المسمى الوظيفي','Name or job title')+'">','search-field'):'')+(range?wrap(tx('من تاريخ','From date'),'dateFrom','<input type="date" id="dateFrom" value="'+from+'">')+wrap(tx('إلى تاريخ','Until date'),'dateTo','<input type="date" id="dateTo" value="'+to+'">'):'')+(dept?wrap(tx('القسم','Department'),'department','<select id="department"><option value="">'+tx('كل الأقسام','All departments')+'</option>'+[...new Set(state.employees.map(e=>e.department))].map(d=>'<option value="'+esc(d)+'" '+(department===d?'selected':'')+'>'+esc(d)+'</option>').join('')+'</select>'):'')+'<span class="filter-note">'+(LIVE?'Google Workspace':tx('بيانات تجريبية • أكتوبر 2026','Sample data • October 2026'))+'</span></div>';
}
